insert into public.feedback_posts (id, author_id, title, body, category, status, vote_count, created_at, status_changed_at) values
('fa4e0006-000c-4000-8000-000000000001', 'fa4e0001-0000-4000-8000-000000000058', 'Let me save a task as a template', 'I post the same cleaning task every month. A post again button would save time.', 'feature', 'planned', 22, now() - interval '22005 minutes', now() - interval '21285 minutes'),
('fa4e0006-000c-4000-8000-000000000002', 'fa4e0001-0000-4000-8000-000000000046', 'Show distance on every task card', 'Hard to tell which tasks are close without opening each one.', 'improvement', 'in_progress', 9, now() - interval '41642 minutes', now() - interval '40922 minutes'),
('fa4e0006-000c-4000-8000-000000000003', 'fa4e0001-0000-4000-8000-00000000004e', 'Map pins overlap in Kondapur', 'When many tasks are in one building the pins hide each other.', 'bug', 'under_review', 10, now() - interval '26616 minutes', now() - interval '25896 minutes'),
('fa4e0006-000c-4000-8000-000000000004', 'fa4e0001-0000-4000-8000-00000000004a', 'Telugu language option', 'My parents would use the app if it was in Telugu.', 'feature', 'planned', 14, now() - interval '38535 minutes', now() - interval '37815 minutes'),
('fa4e0006-000c-4000-8000-000000000005', 'fa4e0001-0000-4000-8000-000000000053', 'Pay in two parts for big jobs', 'For painting jobs I want to pay half at the start and half at the end.', 'feature', 'open', 12, now() - interval '27709 minutes', now() - interval '27709 minutes'),
('fa4e0006-000c-4000-8000-000000000006', 'fa4e0001-0000-4000-8000-000000000045', 'Remind me before the due time', 'A reminder an hour before would help me not miss jobs.', 'improvement', 'done', 5, now() - interval '36264 minutes', now() - interval '35544 minutes'),
('fa4e0006-000c-4000-8000-000000000007', 'fa4e0001-0000-4000-8000-000000000035', 'Dark mode for the map', 'The map is very bright at night.', 'feature', 'open', 23, now() - interval '14615 minutes', now() - interval '14615 minutes'),
('fa4e0006-000c-4000-8000-000000000008', 'fa4e0001-0000-4000-8000-000000000016', 'Add a tip button after the job', 'Sometimes the worker does extra and I want to thank them.', 'other', 'under_review', 10, now() - interval '37302 minutes', now() - interval '36582 minutes'),
('fa4e0006-000c-4000-8000-000000000009', 'fa4e0001-0000-4000-8000-000000000026', 'Chat opens at the oldest message', 'On Android the chat opens at the top instead of the newest message.', 'bug', 'done', 17, now() - interval '7423 minutes', now() - interval '6703 minutes'),
('fa4e0006-000c-4000-8000-00000000000a', 'fa4e0001-0000-4000-8000-000000000056', 'Filter tasks by price', 'Let me hide tasks under ₹300.', 'feature', 'open', 3, now() - interval '23853 minutes', now() - interval '23853 minutes'),
('fa4e0006-000c-4000-8000-00000000000b', 'fa4e0001-0000-4000-8000-00000000005f', 'Bigger photos on task details', 'Photos are small on my phone.', 'improvement', 'declined', 23, now() - interval '42551 minutes', now() - interval '41831 minutes'),
('fa4e0006-000c-4000-8000-00000000000c', 'fa4e0001-0000-4000-8000-00000000001e', 'Verified badge for workers with ID', 'Would make me trust new workers more.', 'feature', 'open', 9, now() - interval '3501 minutes', now() - interval '3501 minutes'),
('fa4e0009-001c-4000-8000-000000000001', 'ec7ca544-48d7-403d-9f54-bcd7312abbd9', 'Show my earnings by week', 'A small chart of what I earned each week would help me plan.', 'feature', 'under_review', 6, now() - interval '4320 minutes', now() - interval '3600 minutes');
